tasks = set()
workers = set()
pairs = set()
for r in rows:
    t = cell('W1::Allowed assignments', f'L{r}')
    w = cell('W1::Allowed assignments', f'M{r}')
    tasks.add(t)
    workers.add(w)
    pairs.add((t, w))

max_covered = 0
task_list = list(tasks)
for r_perm in range(1, len(task_list) + 1):
    for p in itertools.permutations(task_list, r_perm):
        # check if we can assign each task in p to a distinct worker
        def can_match(curr_tasks, curr_workers):
            if not curr_tasks:
                return True
            t = curr_tasks[0]
            for w in list(curr_workers):
                if (t, w) in pairs:
                    curr_workers.remove(w)
                    if can_match(curr_tasks[1:], curr_workers):
                        return True
                    curr_workers.add(w)
            return False

        if can_match(list(p), set(workers)):
            max_covered = max(max_covered, len(p))

result = max_covered

import itertools
sheet = 'W1::Allowed assignments'
rows_data = cells(sheet, 'L812:M820')
valid_pairs = [(r[0], r[1]) for r in rows_data]
max_cov = 0
for r in range(1, len(valid_pairs) + 1):
    for comb in itertools.combinations(valid_pairs, r):
        workers_used = [p[1] for p in comb]
        tasks_used = [p[0] for p in comb]
        if len(workers_used) == len(set(workers_used)) and len(tasks_used) == len(set(tasks_used)):
            if len(tasks_used) > max_cov:
                max_cov = len(tasks_used)
result = max_cov

